// Bridge to the Taskly Racket engine (glaze adapter).
//
// Two transports behind one interface (the family pattern, termpilot):
//  - native: the page runs on the controlled glaze:// origin; calls ride
//    the GLZ1 message handler (window.__glz1, injected at document
//    start). No TCP port exists in production.
//  - http: the page is served by the loopback server (vite dev, the
//    explicit HTTP adapter) and talks plain relative fetch.
//
// Every call is a typed RPC from rivet-schema.json (src/rpc.ts,
// generated by scripts/gen-rpc-types.py). The backend converts camelCase
// JSON DTOs to the schema's field-ordered RVT1 wire values.

interface Glz1 {
  invoke(
    path: string,
    args?: unknown,
    opts?: { method?: string; timeoutMs?: number },
  ): Promise<unknown>;
  on?(name: string, fn: (payload: unknown) => void): void;
}

declare global {
  interface Window {
    __glz1?: Glz1;
  }
}

function nativeBridge(): Glz1 | null {
  return (typeof window !== 'undefined' && window.__glz1) || null;
}

let probe: Promise<boolean> | null = null;

/** True once a backend answers — native bridge present, or /api/health ok. */
export function hasBackend(): Promise<boolean> {
  if (!probe) {
    const g = nativeBridge();
    probe = g
      ? Promise.resolve(true)
      : fetch('/api/health', { method: 'POST' })
          .then((r) => r.ok)
          .catch(() => false);
  }
  return probe;
}

/** POST JSON to the backend; returns the parsed response. */
export async function apiPost<T>(path: string, body?: unknown): Promise<T> {
  const g = nativeBridge();
  if (g) {
    return (await g.invoke(path, body ?? {})) as T;
  }
  const res = await fetch(path, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body ?? {}),
  });
  if (!res.ok) {
    const detail = await res.text();
    // glaze's typed error body carries the engine's user-facing message
    // (bad-param channel); fall back to raw text for transport errors.
    let message = detail.slice(0, 400) || `${path} failed: ${res.status}`;
    try {
      const body = JSON.parse(detail) as { error?: unknown; message?: unknown };
      const m = typeof body.error === 'string' ? body.error : typeof body.message === 'string' ? body.message : null;
      if (m) message = m;
    } catch { /* non-JSON body */ }
    throw new Error(message);
  }
  return (await res.json()) as T;
}

/**
 * Engine push channel. Native carrier: the GLZ1 client delivers event
 * batches through __glz1.on (no SSE endpoint on the controlled origin).
 * HTTP carrier: SSE /glaze/events. Degrades silently where neither is
 * available — never breaks the page.
 */
export function onEngineChanged(cb: (payload: unknown) => void): () => void {
  const g = nativeBridge();
  if (g && typeof g.on === 'function') {
    g.on('changed', cb);
    return () => {};
  }
  try {
    const es = new EventSource('/glaze/events');
    const handler = (e: MessageEvent) => {
      try {
        cb(JSON.parse(e.data));
      } catch {
        cb(e.data);
      }
    };
    es.addEventListener('changed', handler);
    return () => es.close();
  } catch {
    return () => {};
  }
}